def _lengths(g,corners,mouths,at):
    nxt=g.math('MODULO',at+1.,4.)
    read=lambda geo,key,i:c._read(g,geo,key,i)
    return (g.math('ABSOLUTE',read(mouths,'st_cj_parameter',at)-read(corners,'st_cc_sa',at)),
            read(corners,'st_cc_radius',at)*g.math('ABSOLUTE',read(corners,'st_cc_sweep',at)),
            g.math('ABSOLUTE',read(mouths,'st_cj_parameter',nxt)-read(corners,'st_cc_sb',at)))


def _knots(g,table,owner):
    return c._select(g,table,c.named(g,'st_cg_break','BOOLEAN')*
                     g.math('COMPARE',c.named(g,'st_cg_owner','INT'),owner))


