    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    ri=g.node('GeometryNodeRepeatInput','Distribute opposite-side extra intervals without dropping knots')
    ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
