    at=c.V(g,ri.outputs['Iteration']);a=c._read(g,knots,'st_cg_t',at);b=c._read(g,knots,'st_cg_t',at+1.)
    needed=g.math('CEIL',(b-a)*length/cell)+g.math('FLOOR',extra*b)-g.math('FLOOR',extra*a)
    segment=c._store(g,c._line(g,g.math('MAXIMUM',1.,needed)),'st_cq_t',a+(b-a)*i/g.math('MAXIMUM',1.,needed))
    g.bind(boundary._join(g,ri.outputs['Geometry'],segment),ro.inputs['Geometry'])
    final=c._store(g,c._line(g,1),'st_cq_t',1.);geo=boundary._join(g,ro.outputs['Geometry'],final)
    t=c.named(g,'st_cq_t');previous=c._read(g,geo,'st_cq_t',g.math('MAXIMUM',0.,i-1.))
    valid=c.V(g,inp.outputs['Input Valid'])*g.math('COMPARE',c._count(g,geo),total+1.)
    valid=valid*c._stat(g,geo,c.choose(g,g.math('LESS_THAN',i,.5),1.,g.math('GREATER_THAN',t-previous,1e-8)))
    out=g.node('NodeGroupOutput');g.bind(geo,out.inputs['Geometry']);g.bind(valid,out.inputs['Valid']);return g.g


