def _chart(g,inp,owner,t,v,*,allow_taper=False,compound=False,continuations=False,port_paths=False,span_compounds=False,chain_sides=False,interpolation=False):
    lookup=g.node('GeometryNodeGroup');lookup.node_tree=spline.evaluate()
