def _crown(g,mouths,at,*,interpolation=False):
    read=lambda key,kind='FLOAT':c._read(g,mouths,'st_cj_'+key,at,kind)
    axis=c._right(c._vec(g,read('tangent','FLOAT_VECTOR')))
    if interpolation:
        from .curved_exact_profile_nodes import mouth_axis
        axis=mouth_axis(g,mouths,at)
    return c._add(c._vec(g,read('position','FLOAT_VECTOR')),c._scale(axis,.5*read('width')*read('half','INT')))


